e(shp_path)) #add the storm id file shp &lt;- shp %&gt;% mutate(storm_id = file_prefix) #overwrite shapefile st_write(shp, shp_path, delete_dsn = TRUE, quiet = TRUE) } We need to change the date and time formats to be consistent between the point and polygon files for easier comparison. We will start with the points files. #Create a new directory for processed files output_dir &lt;- file.path(base_dir, &quot;processed&quot;) #processing for just the _pts.shp files to normalize dates and times base_dir &lt;- r&quot;(./data/HurricaneRawData/nhc_best_tracks)&quot; output_dir &lt;- file.path(base_dir, &quot;processed&quot;) dir.create(output_dir, showWarnings = FALSE) #get all the shapefiles recursively shp_files &lt;- list.files(base_dir, pattern = &quot;_pts\.shp$&quot;, recursive = TRUE, full.names = TRUE) #recursively alter the pts files to the normalized date and time fields with ids for (shp_path in shp_files) { message(&quot;Processing: &quot;, shp_path) shp &lt;- st_read(shp_path, quiet = TRUE) #files had different formats for dates and times, this normalizes them #important step to combine everything for later analysis shp &lt;- shp %&gt;% mutate( mm = str_pad(as.integer(unname(month_map[tolower(MONTH)])), 2, pad = &quot;0&quot;), dd = str_pad(as.integer(DAY), 2, pad = &quot;0&quot;), hh = str_sub(HHMM, 1, 2), event_id = tolower(paste0(storm_id, mm, dd, hh)) ) #preserve folder structure in output rel_path &lt;- path_rel(shp_path, start = base_dir) rel_path &lt;- sub(&quot;^processed/&quot;, &quot;&quot;, rel_path) out_path &lt;- file.path(output_dir, rel_path) dir_create(dirname(out_path)) #write output st_write(shp, out_path, delete_dsn = TRUE, quiet = TRUE) } The radii (polygon) files also need to be changed in a similar way to the points files. #slightly different process for the _radii file they already have the synoptime field and those just need to be modified shp_files &lt;- list.files(base_dir, pattern = &quot;_radii\.shp$&quot;, recursive = TRUE, full.names = TRUE) #recursively alter the pts files to fie normalized date and time fields with ids for (shp_path in shp_files) { message(&quot;Processing: &quot;, shp_path) shp &lt;- st_read(shp_path, quiet = TRUE) #create matching event_id to the points fields so they can be related (since they have different kinds of information) shp &lt;- shp %&gt;% mutate( event_id = tolower( paste0(storm_id, substr(SYNOPTIME, 5, nchar(SYNOPTIME))) #this will be storm id, date, and UTC hour in 24 hour format i.e. [al01][20250831][12] ) ) #different kind of id, radii refers to the range of wind at that knot level i.e. _34 would be 34 knot wind shp &lt;- shp %&gt;% mutate( event_r_id = tolower( paste0(storm_id, substr(SYNOPTIME, 5, nchar(SYNOPTIME)), &quot;_&quot;, RADII)#this will be storm id, date, and UTC hour in 24 hour format, and radii distance i.e. [al01][20250831][12][_34] ) ) #preserve folder structure rel_path &lt;- path_rel(shp_path, start = base_dir) out_path &lt;- file.path(output_dir, rel_path) dir_create(dirname(out_path)) #write output st_write(shp, out_path, delete_dsn = TRUE, quiet = TRUE) } 5.3 Compute Intersections Now that the hurricane files are prepared properly, the associated points data of interest, (in this case hospitals), can be used within the files. The point files in this example have a series of months and years in columns when surveys were conducted, a latitude and longitude column where we can identify First we load all the storms. #where all the processed files are storms_dir &lt;- r&quot;(./data/HurricaneRawData/nhc_best_tracks/processed)&quot; setwd(&#39;C:/Users/matth/Climate_and_Health/bookdown_project&#39;) #get all the radii shapefiles #I settled on radii, because its the reach of the wind cols &lt;- c(&quot;event_id&quot;, &quot;event_r_id&quot;, &quot;storm_id&quot;) storms_list &lt;- purrr::map(shp_files, function(x) { st_read(x, quiet = TRUE) %&gt;% select(any_of(cols)) }) #get all the storms all_storms &lt;- dplyr::bind_rows(storms_list) all_storms &lt;- st_transform(all_storms, 4326) all_storms &lt;- st_make_valid(all_storms) all_storms &lt;- st_transform(all_storms, 3978) all_storms$months &lt;- ym(str_sub(all_storms$event_id, 5, 10)) Now that all the data is loaded and ready, the intersection with all the points of interest needs to be performed and a number of data outputs are created. A long table of storms and intersections with hospitals. A wide table with the ID’s of the surveyed locations and a matrix of 1’s and 0’s identifying if they were impacted by a storm during the previous 24 months. A table with daily intersection information for the month the survey was conducted. A long table with only intersection information. #the website of interest for tracks website &lt;- &#39;https://www.nhc.noaa.gov/gis/archive_besttrack.php&#39; #lookup table with names that was created in an earlier step storm_names_dir &lt;- r&quot;(./data/HurricaneRawData/storm_lookup_table.csv)&quot; #common columns long_col &lt;- &quot;long&quot; lat_col &lt;- &quot;lat&quot; survey_id_col &lt;- &quot;hospital_id&quot; survey_year_col &lt;- &quot;survey_year&quot; survey_month_col &lt;- &quot;survey_month&quot; #to keep cols &lt;- c(&quot;geometry&quot;, &quot;event_id&quot;, &quot;event_r_id&quot;, &quot;storm_id&quot;) #buffer distances in metres to go around point of interest bufs &lt;- c(25000)#, 0, 50000, 100000) #years of survey date batches for naming conventions (only one batch in this tutorial) years &lt;- c(&#39;all&#39;) #this is paried with the above years, should match up! survey_hospitals &lt;- r&quot;(./data/odhf_hospitals.csv)&quot; dirs &lt;- c(survey_hospitals) #results storage hurricane_results &lt;- list() #this is a double loop, the first one goes through each survey year of interest for (k in seq_along(years)){ message(&quot;Naming suffix: &quot;, years[k]) #the second loop applies the buffer size to the survey data for intersection analysis #between storm pathway and survey data for (i in seq_along(bufs)){ message(&quot;Point buffer extent: &quot;, bufs[i]/1000, &quot; km&quot;) #read the survey data survey_data &lt;- read.csv(dirs[k]) #convert the survey data to an sf object for the intersection survey_sf &lt;- st_as_sf( #eliminate the Nas survey_data[!is.na(survey_data[[long_col]]) &amp; !is.na(survey_data[[lat_col]]), ], coords = c(long_col, lat_col), crs = 4326 ) #make sure its the appropriate crs #survey_sf &lt;- st_transform(survey_sf, 4326) survey_sf &lt;- st_transform(survey_sf, 3978) #apply the buffer to the survey points survey_buffer &lt;- st_buffer(survey_sf, bufs[i]) #create a date type column from the survey year and survey month columns survey_buffer$months &lt;- ym(paste0(survey_buffer[[survey_year_col]], survey_buffer[[survey_month_col]])) survey_buffer$survey_id &lt;- paste(survey_buffer[[survey_id_col]], survey_buffer[[survey_month_col]], survey_buffer[[survey_year_col]], sep=&quot;_&quot;) #get all storms that happen within 30 months of the earliest survey date and the latest survey month of that year #this could be a pretty variable range of dates all_storms_within_range &lt;- all_storms %&gt;% filter(months &gt;= (min(survey_buffer$months)-months(30)) &amp; months &lt;= max(survey_buffer$months)) #do the intersection between the surveys and all of those storms intersection &lt;- st_intersects(survey_buffer, all_storms_within_range, sparse = TRUE) #build the dataframe intersection_df &lt;- map2_dfr( #for each intersection seq_along(intersection), #create a little tibble of point, storm, survey, and if it intersects #creates an association between each poi and storm intersect event and attaches the date of the survey intersection, ~ tibble( point_id = survey_sf[[survey_id_col]][.x], storm_id = all_storms_within_range$event_r_id[.y], survey_date = survey_buffer$months[.x], intersects = 1 ) ) #get the storm names storm_lookup &lt;- read.csv(storm_names_dir, sep=&quot;,&quot;) #preserve the intersection dataframe matrix_df &lt;- intersecti